package io.clipbridge.android;
import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.database.Cursor;
import android.graphics.*;
import android.net.Uri;
import android.os.*;
import android.provider.OpenableColumns;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;
public final class ShareActivity extends Activity {
    private final List<Uri> uris=new ArrayList<>();private final List<JSONArray> groups=new ArrayList<>();private final List<String> names=new ArrayList<>();private final ExecutorService io=Executors.newSingleThreadExecutor();private CheckBox asFile;private Spinner targets;private TextView status;private Button send;
    public void onCreate(Bundle b){super.onCreate(b);try{
        Intent intent=getIntent();if(Intent.ACTION_SEND.equals(intent.getAction())){Uri uri=intent.getParcelableExtra(Intent.EXTRA_STREAM);if(uri!=null)uris.add(uri);}else if(Intent.ACTION_SEND_MULTIPLE.equals(intent.getAction())){ArrayList<Uri> items=intent.getParcelableArrayListExtra(Intent.EXTRA_STREAM);if(items!=null)uris.addAll(items);}else throw new IllegalArgumentException();
        if(uris.isEmpty()||uris.size()>20)throw new IllegalArgumentException("一次选择 1～20 个文件。");for(Uri uri:uris)if(!"content".equals(uri.getScheme()))throw new IllegalArgumentException("请选择支持分享的内容文件。");
        Bundle settings=getContentResolver().call(BridgeProvider.URI,"profiles",null,null);if(settings.getBoolean("paused"))throw new IllegalArgumentException("全部同步已暂停，请先在 ClipBridge 中恢复。");JSONArray profiles=new JSONArray(settings.getString("profiles"));Map<String,JSONArray> map=new LinkedHashMap<>();Map<String,String> titles=new HashMap<>();for(int i=0;i<profiles.length();i++){JSONObject p=profiles.getJSONObject(i);if(!p.optBoolean("enabled",true))continue;String pair=p.getJSONObject("config").getString("pair"),group=p.optString("peerIdentity");if(group.length()!=32)group=pair;map.computeIfAbsent(group,k->new JSONArray()).put(pair);titles.put(group,p.optString("name","接收设备"));}for(String key:map.keySet()){groups.add(map.get(key));names.add(titles.get(key)+" · "+map.get(key).length()+" 条通道");}if(groups.isEmpty())throw new IllegalArgumentException("请先打开 ClipBridge，添加并开启配置。");
        LinearLayout layout=new LinearLayout(this);layout.setOrientation(LinearLayout.VERTICAL);layout.setPadding(36,42,36,30);TextView title=new TextView(this);title.setText("通过 ClipBridge 发送");title.setTextSize(23);layout.addView(title);status=new TextView(this);status.setText("已选择 "+uris.size()+" 项，单文件上限 100 MB。\n图片发往所有已开启设备；普通文件选择下方目标，等待对方同意。");layout.addView(status);targets=new Spinner(this);targets.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,names));layout.addView(targets);asFile=new CheckBox(this);asFile.setText("图片也作为文件发送（保留原始格式）");layout.addView(asFile);send=new Button(this);send.setText("发送");send.setOnClickListener(v->begin());layout.addView(send);setContentView(layout);
    }catch(Exception e){Toast.makeText(this,e instanceof IllegalArgumentException?e.getMessage():"无法读取分享内容。",Toast.LENGTH_LONG).show();finish();}}
    private void begin(){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},51);return;}boolean files=asFile.isChecked();int target=targets.getSelectedItemPosition();send.setEnabled(false);status.setText("正在准备文件，请稍候…");ClipData grants=ClipData.newRawUri("ClipBridge share",uris.get(0));for(int u=1;u<uris.size();u++)grants.addItem(new ClipData.Item(uris.get(u)));Intent receiver=new Intent(this,TransferService.class).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);receiver.setClipData(grants);startForegroundService(receiver);io.execute(()->{try{for(Uri uri:uris)prepare(uri,files,target);runOnUiThread(()->{Toast.makeText(this,"已加入发送队列，可在通知中查看进度。",Toast.LENGTH_LONG).show();finish();});}catch(Throwable e){runOnUiThread(()->{status.setText(e instanceof IllegalArgumentException?e.getMessage():"准备文件失败，请检查读取权限、格式和存储空间。");send.setEnabled(true);});}});}
    public void onRequestPermissionsResult(int request,String[] permissions,int[] results){super.onRequestPermissionsResult(request,permissions,results);if(request==51&&results.length>0&&results[0]==PackageManager.PERMISSION_GRANTED)begin();else Toast.makeText(this,"需要通知权限才能确认接收与显示传输进度。",Toast.LENGTH_LONG).show();}
    private void prepare(Uri uri,boolean asFile,int target)throws Exception{String mime=getContentResolver().getType(uri),name="shared-file";long known=-1;try(Cursor cursor=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME,OpenableColumns.SIZE},null,null,null)){if(cursor!=null&&cursor.moveToFirst()){int n=cursor.getColumnIndex(OpenableColumns.DISPLAY_NAME),s=cursor.getColumnIndex(OpenableColumns.SIZE);if(n>=0&&!cursor.isNull(n))name=cursor.getString(n);if(s>=0&&!cursor.isNull(s))known=cursor.getLong(s);}}if(known>MediaProtocol.MAX)throw new IllegalArgumentException("单文件上限 100 MB，大文件请改用网盘或其他传输方式。");name=MediaProtocol.safe(name);File directory=new File(getCacheDir(),"share");directory.mkdirs();File original=new File(directory,UUID.randomUUID()+".source"),generated=null;try{
            try(InputStream input=getContentResolver().openInputStream(uri);OutputStream output=new FileOutputStream(original)){if(input==null)throw new IOException();byte[] buffer=new byte[65536];long size=0;int n;while((n=input.read(buffer))!=-1){size+=n;if(size>MediaProtocol.MAX)throw new IllegalArgumentException("文件超过 100 MB，请使用其他传输方式。");output.write(buffer,0,n);}}
            boolean image=!asFile&&mime!=null&&mime.startsWith("image/");File payload=original;if(image){BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeFile(original.getAbsolutePath(),bounds);if(bounds.outWidth<=0||bounds.outHeight<=0||(long)bounds.outWidth*bounds.outHeight>20000000)throw new IllegalArgumentException("图片尺寸或格式不支持，请勾选“图片也作为文件发送”。");Bitmap bitmap=ImageDecoder.decodeBitmap(ImageDecoder.createSource(original),(decoder,info,source)->decoder.setAllocator(ImageDecoder.ALLOCATOR_SOFTWARE));if(bitmap==null)throw new IOException();payload=new File(directory,UUID.randomUUID()+".png");generated=payload;try(OutputStream output=new FileOutputStream(payload)){if(!bitmap.compress(Bitmap.CompressFormat.PNG,100,output))throw new IOException();}finally{bitmap.recycle();}name=MediaProtocol.safe(name.replaceFirst("\\.[^.]*$","")+".png");if(payload.length()>MediaProtocol.MAX)throw new IllegalArgumentException("图片转换后超过 100 MB，请作为文件发送。");}
            try{List<JSONArray> destinations=image?groups:Collections.singletonList(groups.get(target));for(JSONArray pairs:destinations){File copy=new File(directory,UUID.randomUUID()+".queued");java.nio.file.Files.copy(payload.toPath(),copy.toPath());startForegroundService(new Intent(this,TransferService.class).putExtra("action","stage").putExtra("path",copy.getAbsolutePath()).putExtra("name",name).putExtra("kind",image?"image":"file").putExtra("targets",pairs.toString()));}}finally{if(payload!=original)payload.delete();}
        }finally{original.delete();if(generated!=null)generated.delete();}}
    public void onDestroy(){io.shutdown();super.onDestroy();}
}
